 bool coopCheckBaseDone;
 [Rpc(MultiplayerApi.RpcMode.AnyPeer,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopCheckBaseAck(){if(coopCheck&&CoopHost&&coopActors.ContainsKey(Multiplayer.GetRemoteSenderId()))coopCheckBaseDone=true;}
 bool coopCheckFinished,coopCheckSawDungeon,coopCheckRejoined,coopCheckStoryRead,coopCheckLetterShown;
 [Rpc(MultiplayerApi.RpcMode.AnyPeer,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopCheckStoryAck(){if(coopCheck&&CoopHost&&coopActors.ContainsKey(Multiplayer.GetRemoteSenderId()))coopCheckStoryRead=true;}
[Rpc(MultiplayerApi.RpcMode.AnyPeer,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)] void CoopCheckRejoin(){if(coopCheck&&CoopHost&&coopActors.ContainsKey(Multiplayer.GetRemoteSenderId()))coopCheckRejoined=true;}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]
 async void CoopCheckStage(string stage,Vector3 target){if(!coopCheck||coopCheckRole!="client")return;try{if(stage=="residential-salvage"){await ClientResidentialChecks(target);return;}if(stage=="field-kit"){await ClientFieldKitChecks(target);return;}if(stage=="opening-gate"){await ClientOpeningChecks(target);return;}if(stage=="hunting-harvest"){await ClientHuntingChecks();return;}if(stage.StartsWith("community-social-")){await ClientCommunitySocialChecks(stage);return;}if(stage.StartsWith("world-works-")){await ClientWorldWorksChecks(stage,target);return;}if(stage.StartsWith("journey-")){await ClientJourneyChecks(stage,target);return;}if(stage=="field-content"){await ClientContentAtlasChecks(target);return;}if(stage=="field-job"){await ClientFieldJobChecks(target);return;}if(stage=="settlement-development"){await ClientSettlementCampaignChecks(target);return;}if(stage=="rescue-companion"){await ClientRescueDogChecks(target);return;}if(stage=="living-community"){await ClientLivingChecks(target);return;}if(stage.StartsWith("gunplay-")){await ClientGunplayChecks(stage,target);return;}if(stage.StartsWith("campaign-")){await ClientCampaignChecks(stage,target);return;}if(stage.StartsWith("expansion-")){await ClientExpansionChecks(stage,target);return;}if(stage.StartsWith("crash-")){await ClientCrashChecks(stage,target);return;}if(stage.StartsWith("checkpoint-")){await ClientCheckpointChecks(stage,target);return;}if(stage=="birthday-cake"){await ClientBirthdayChecks(target);return;}if(stage.StartsWith("lastletter-")){await ClientLastLetterChecks(stage,target);return;}if(stage.StartsWith("fever-")){await ClientFeverChecks(stage,target);return;}if(stage.StartsWith("family-")){await ClientFamilyChecks(stage,target);return;}if(stage=="base"){await CoopWait(()=>game.Building.Pieces.Any(p=>p.Id=="coop-check-storage"),"Storage replica missing");int before=game.Craft.Materials[0];CoopRequest("baseuse","coop-check-storage|deposit|0");await CoopWait(()=>game.Building.Pieces.First(p=>p.Id=="coop-check-storage").Stock[0]==10&&game.Craft.Materials[0]==before-10,"Deposit not authoritative");CoopRequest("baseuse","coop-check-storage|withdraw|0");await CoopWait(()=>game.Building.Pieces.First(p=>p.Id=="coop-check-storage").Stock[0]==0&&game.Craft.Materials[0]==before,"Withdrawal failed conservation");int research=Array.FindIndex(ExpeditionRecipe.All,r=>r.Kind=="armor"&&r.Tier==1&&r.Result==11);int points=game.Craft.ResearchPoints;CoopRequest("research",research.ToString());await CoopWait(()=>game.Knows(ExpeditionRecipe.All[research])&&game.Craft.ResearchPoints==points-1,"Research point spend not synchronized");CoopRequest("talent","health");await CoopWait(()=>game.Career.Rank("health")==1&&game.MaxHealth>=110,"Talent purchase not authoritative");await ClientWeaponPartChecks();RpcId(1,nameof(CoopCheckBaseAck));}else if(stage=="story"){CoopRequest("interact");await CoopWait(()=>coopCheckLetterShown,"Guest letter UI missing");if(game.Profile.Journal.Seen.Count==0)await CoopWait(()=>game.Profile.Journal.Seen.Count>0,"Guest journal not synchronized");CloseMenu();RpcId(1,nameof(CoopCheckStoryAck));}else if(stage=="explore"){await ClientIndependentExploration(target);}else if(stage=="shoot"){await CoopWait(()=>infected.Any(e=>e.Id=="coop-check/infected"),"Enemy replica absent");await CoopWait(()=>infected.Any(e=>e.Id=="fauna/deer/coop-check"),"Animal replica absent");if(!infected.Find(e=>e.Id=="fauna/deer/coop-check").Visual.HasNode("Leg3"))throw new Exception("Animal replica has wrong rig");player.Rotation=Vector3.Zero;pitch=0;camera.Rotation=Vector3.Zero;await CoopDelay(.3);CoopRequest("shoot");}else if(stage=="bandage"){if(game.Life.Wounds.Count!=1)throw new Exception("Host damage was not replicated");CoopRequest("bandage");}else if(stage=="done")coopCheckFinished=true;}catch(Exception ex){GD.PushError(ex.ToString());GetTree().Quit(1);}}
